const e=$json; const input=e.input??{}; const query=String(input.query??'').trim(); const top_k=Number(input.top_k??5); const asset_type=input.asset_type??null;
if(query.length<4||query.length>1000||!Number.isInteger(top_k)||top_k<5||top_k>20||asset_type!==null&&!['cv','project','stack'].includes(asset_type))throw Error('Invalid RAG search input');
return {json:{schema_version:1,job_id:e.job_id??null,lead_id:e.lead_id??null,operation:'rag_search',context:e.context??null,input:{query,top_k,asset_type},result:null,warnings:[]}};

const envelope=$('Validate search envelope').item.json; const points=$json.result?.points??[]; const docs=new Map();
for(const point of points){const p=point.payload??{};if(p.source!=='supabase_storage'||!p.document_id||!p.source_bucket||!p.source_path)continue;
const id=String(p.asset_type??'')+':'+p.document_id; const score=Number(point.score??0); const previous=docs.get(id);
if(!previous||score>previous.score)docs.set(id,{document_id:p.document_id,asset_type:p.asset_type,title:p.title??p.document_id,source_bucket:p.source_bucket,source_path:p.source_path,section:p.sections?.[0]??null,excerpt:String(p.text??'').slice(0,1000),score});}
const documents=[...docs.values()].sort((a,b)=>b.score-a.score).slice(0,envelope.input.top_k);
return {json:{...envelope,result:{documents},warnings:documents.length?[]:['No indexed document matched the filters']}};
